// Import of required libraries
import { test, getBaseUrl, newSkyrampPlaywrightPage } from '@skyramp/skyramp';
import { expect } from '@playwright/test';
import { setProjectName, openExportImageDialog } from './skyrampUtils';

const pageTimeout = 15000;

// URL for test requests
const baseUrl = getBaseUrl("SKYRAMP_TEST_BASE_URL", "http://localhost:3000");

test.use({
    viewport: { width: 1280, height: 900 },
});

test('testUi', async ({ page }) => {
    test.setTimeout(93000);

    // set default timeout for all locator/page actions in this test
    page.setDefaultTimeout(pageTimeout);
    // Wrap playwright page with Skyramp page
    page = newSkyrampPlaywrightPage(page);

    await page.goto(baseUrl);
    await setProjectName(page, 'quarterly:report');
    await page.goto(`${baseUrl}/`);
    await openExportImageDialog(page);

    // The scene name carries an OS-illegal ':' - the same value the JSON export
    // dialog refuses to export with. ImageExportDialog.tsx was not touched by this
    // PR, so its PNG/SVG exports still write that name straight to the download
    // filename, which is the failure the PR set out to fix.
    await expect(page.getByRole('button', { name: 'Export to PNG' })).toBeDisabled();
    await expect(page.getByRole('button', { name: 'Export to SVG' })).toBeDisabled();
    await expect(page.getByRole('heading', { name: 'Export image' })).toBeVisible();
});
